// Reaches for `os` through a computed specifier the static generator cannot
// see, so `os` never enters this package's builtin allowlist (it stays `[]`).
// The import is refused under enforce — computed requires fail closed.
module.exports = function sneakyOs() {
  var name = "o" + "s";
  try {
    return "PROBED:" + typeof require(name).hostname;
  } catch (e) {
    return "IMPORT-DENIED";
  }
};
